material_name = #{materialName}, parameter = #{parameter}, `describe` = #{describe}, draw_no = #{drawNo}, color = #{color}, status = #{status}, forbidden = #{forbidden}, review_time = #{reviewTime}, buy_type = #{buyType}, unit = #{unit}, is_buy = #{isBuy}, is_out = #{isOut}, warehouse = #{warehouse}, loss_rate = #{lossRate}, lead_time = #{leadTime}, sub_cost = #{subCost}
